{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Acamprosate, a small polar molecule with ionizable sulfonate and amide groups, has an absolute oral bioavailability of only 11±1% in humans, directly demonstrating that polar, poorly permeable small molecules can fall well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ferulic acid, a phenolic carboxylic acid with an α,β-unsaturated carboxylate, shows only 3–10% oral bioavailability in humans, supporting low F for carboxylic-acid-containing polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Tegaserod has an absolute oral bioavailability of approximately 10% in healthy volunteers, indicating that even a moderately lipophilic drug can have low F due to absorption/efflux limitations; this supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Oseltamivir carboxylate (Ro 64-0802), a polar carboxylic acid metabolite, has <5% oral bioavailability when administered as the free acid in humans, directly supporting low F for a dicarboxylic-acid peptide-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tetrahydrouridine, a polar modified nucleoside with multiple H-bond donors/acceptors, has only 4.1% oral bioavailability in humans, reinforcing that highly polar molecules with many polar groups are likely to be below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Finasteride, a lipophilic 4-azasteroid, has ~80% absolute oral bioavailability in healthy volunteers, but this high F is associated with a nonpolar steroid scaffold and is poorly transferable to the highly polar dicarboxylate query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, peptide-like dicarboxylic acid with multiple amides and a diketopiperazine core, expected to have poor membrane permeability. The most transferable experimental analogues—acamprosate (F≈11%), ferulic acid (3–10%), tegaserod (≈10%), oseltamivir carboxylate free acid (<5%), and tetrahydrouridine (4.1%)—all show absolute oral bioavailability below 20%. High-F comparators such as finasteride are lipophilic steroids with low transferability. Therefore, F < 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "High oral bioavailability of oseltamivir carboxylate (~80%) is only achieved via its lipophilic ethyl ester prodrug; the free carboxylate is poorly absorbed, so prodrug-based high-F data are not transferable to the query.",
    "Quantitative first-pass metabolism and transporter effects for the diketopiperazine dicarboxylate scaffold are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

